import{APIService}from"./api.js";export class AuthService{static getRoles(){return{PARENT:"parent",TEACHER:"teacher",ADMIN:"admin"}}static getCurrentUser(){const e=localStorage.getItem("school_app_user");if(!e)return null;try{return JSON.parse(e)}catch(e){return console.error("AuthService: session corrupted",e),this.logout(),null}}static setCurrentUser(e){localStorage.setItem("school_app_user",JSON.stringify(e))}static getAuthToken(){return localStorage.getItem("school_app_token")}static setAuthToken(e){e?localStorage.setItem("school_app_token",e):localStorage.removeItem("school_app_token")}static checkAuth(e){const t=this.getCurrentUser();return t?!(e&&!e.includes(t.role))||(this.redirectUserToRoleDashboard(t.role),!1):(window.location.href="index.html",!1)}static redirectUserToRoleDashboard(e){const t=this.getRoles();switch(e){case t.PARENT:window.location.href="parent.html";break;case t.TEACHER:window.location.href="teacher.html";break;case t.ADMIN:window.location.href="admin.html";break;default:window.location.href="index.html"}}static logout(){localStorage.removeItem("school_app_user"),localStorage.removeItem("school_app_token"),window.location.href="index.html"}static async fetchStamp(){const e=await fetch("/api/auth/stamp");if(!e.ok)throw new Error(`Failed to obtain security stamp: HTTP ${e.status}`);return(await e.json()).stamp}static async sendOtp(e){const t=await this.fetchStamp(),s=await fetch("/api/auth/otp/send",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({phone:e,stamp:t})}),o=await s.json();if(!s.ok||!o.success){const e=new Error(o.error||"Failed to dispatch verification code.");throw e.retry_after_seconds=o.retry_after_seconds,e}return o}static async verifyOtp(e,t){const s=await fetch("/api/auth/otp/verify",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({phone:e,otp:t})}),o=await s.json();if(!s.ok||!o.success)throw new Error(o.error||"Invalid or expired verification code.");return o.token&&this.setAuthToken(o.token),o.user&&this.setCurrentUser(o.user),o}static async validateSession(){const e=this.getAuthToken(),t=this.getCurrentUser();if(!e||!t)return!1;try{const t=await fetch("/api/auth/verify-session",{headers:{Authorization:`Bearer ${e}`}});if(t.ok){if((await t.json()).valid)return!0}}catch(e){return console.warn("Session verification warning (continuing with offline session):",e),!0}return!1}static async verifyPhoneRegistered(e){try{if(await APIService.get(`school/admin/${e}`))return{isRegistered:!0,role:"admin"};const t=await APIService.get(`school/login_mappings/${e}`);return t?{isRegistered:!0,role:t.role,mapData:t}:{isRegistered:!1}}catch(e){throw console.error("AuthService: registration check failed",e),e}}static async executeLogin(e,t){if("0000"!==t&&"000000"!==t&&"123456"!==t)throw new Error("Invalid verification code. Please enter '0000' to login.");const s=await this.verifyPhoneRegistered(e);if(!s.isRegistered)throw new Error("Invalid phone number: This mobile number is not registered in the school database.");const o=this.getRoles();let r=null;if("admin"===s.role)r={role:o.ADMIN,id:"ADM-"+e.slice(-4),name:"Administrator",phone:e};else{const t=s.mapData;if("teacher"===t.role||"principal"===t.role){const s=await APIService.get(`school/teachers/${t.studentId}`);if(!s)throw new Error("Teacher profile record missing in database.");let a="";a=s.name&&"object"==typeof s.name?`${s.name.first||""} ${s.name.middle||""} ${s.name.last||""}`.replace(/\s+/g," ").trim():s.name||"Faculty Member",r={role:o.TEACHER,id:t.studentId,name:a,phone:s.phone||e,photo:s.photo||"https://images.unsplash.com/photo-1544717305-2782549b5136?w=150",subjects:s.subjects||[],assignedClasses:s.assignedClasses||[],classTeacherOf:s.classTeacherOf||"none",schedule:s.schedule||[{period:"1st",class:s.assignedClasses?s.assignedClasses[0]:"10-A",subject:s.subjects?s.subjects[0]:"Mathematics",time:"10:00 AM"}]}}else if("admin"===t.role)r={role:o.ADMIN,id:t.studentId||"A-001",name:"Admin Staff",phone:e};else{const s=await APIService.get(`school/students/${t.studentId}`);if(!s)throw new Error("Student profile record missing in database.");r={role:o.PARENT,id:"P-"+e.slice(-4),name:s.parentName||"Student Parent",phone:e,studentId:t.studentId,studentName:s.name||"Student",studentClass:s.class||"1",studentPhoto:s.photo||"https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=150"}}}if(r)return this.setCurrentUser(r),r;throw new Error("Failed to construct user session.")}}